import { ReactChildren, ReactElement } from 'react';
import toArray from 'rc-util/es/Children/toArray';

// TODO: 单测：校验每次能过滤到正确的 StepPane
/**
 * 解析 FormStep 的 JSX children，并从一级目录中，按顺序找出所有 StepPane
 * @param children
 * @returns
 */
export const parseJSXSteps = (children?: ReactChildren) => {
  // 解析出所有的子 Item
  const childNodes = toArray(children, { keepEmpty: false });
  const steps = childNodes?.filter(node => {
    const childPropsComponent = (node as ReactElement)?.props?.component;
    // 对应 field.component 属性
    const [component] = childPropsComponent || [];
    const name = component?.displayName || component?.name;
    return name === 'StepPane';
  });
  return steps || [];
};
